sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    try {
        var tempGr = new GlideRecord('x_1425578_itsm_u_0_incident_temp');
        tempGr.initialize();
        // Use the CORRECT API field names (e.g., with "u_" prefix):
        tempGr.incident_number = current.number; // ✅ Correct API name
        tempGr.short_description = current.short_description; // ✅ Correct API name
        var sysID = tempGr.insert();
        gs.info('Record inserted into incident_temp: ' + sysID);
    } catch (e) {
        gs.error('Error inserting record: ' + e.message);
    }
})(current, previous);
